ValidationRule.errorConditionFormula:
AND(
NOT($Setup.Metadata_Activation_Settings__c.Disable_VR__c && OR(ISBLANK($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c), CONTAINS($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c, 'Opportunity'))),
/*--Block Stage 5 -> 6 when Booking Verification is Rejected or Blank or Hold-Pending Correction--*/
ISPICKVAL(StageName, '6 - Setup'), ISPICKVAL(PRIORVALUE(StageName), '5 - Signed/PO in'), Booking_Verification_Validation__c = True,
OR( ISPICKVAL( Deal_Validation__c , 'Reject'), ISPICKVAL( Deal_Validation__c , ''), ISPICKVAL( Deal_Validation__c , 'Hold-Pending Correction') ),
/*--Limit to Any Std Record Types--*/ OR( ( RecordType.DeveloperName ) = 'Standard_Opportunity', ( RecordType.DeveloperName ) = 'IMLA_Standard_Opportunity', ( RecordType.DeveloperName ) = 'IMAP_Standard_Opportunity', ( RecordType.DeveloperName ) = 'IME_Standard_Opportunity' ),
/*--Bypass Admins from this VR--*/ $Profile.Name <> 'System Administrator', $Profile.Name <> 'IM_Custom Sys Admin',
/*--Bypass eComm from this VR--*/ $Label.IMExpress_Opp_Owner!= OwnerId, NOT($Permission.VR_Bypass_Permission)
)
